#[no_mangle]
pub unsafe extern "C" fn optimal_binary_search_tree(v:*const i64,n:usize)->i64{if v.is_null()||n<2||n>33{return -1}let k=*v;if !(1..=32).contains(&k)||n!=k as usize+1{return -1}let k=k as usize;let mut freq=[0i64;32];let mut prefix=[0i64;33];let mut dp=[[0i64;32];32];for i in 0..k{let f=*v.add(i+1);if !(0..=1000).contains(&f){return -1}freq[i]=f;prefix[i+1]=prefix[i]+f;dp[i][i]=f;}for width in 2..=k{for start in 0..=k-width{let end=start+width-1;let total=prefix[end+1]-prefix[start];let mut best=i64::MAX;for root in start..=end{let cost=total+(if root>start{dp[start][root-1]}else{0})+(if root<end{dp[root+1][end]}else{0});if cost<best{best=cost}}dp[start][end]=best;}}dp[0][k-1]}
